import json,numpy as np
from PIL import Image
m=json.load(open('/app/output/drawer_handle_above_view_meta.json'));q=np.array(m['proprio']['now'][6:13]);im=np.array(Image.open('/app/output/drawer_handle_above_view_robot_wrist.png'));d=np.load('/app/output/drawer_handle_above_view_depth.npy').astype(float)
p=np.array([[.1199,0,.5512],[.1199,-.0054,.6796],[.1199,-.0117,.89],[.1199,-.0181,1.1004],[.1199,-.0245,1.3088],[.1199,-.0247,1.4147],[.1199,-.0249,1.5207]]);a=np.array([[0,0,-1],[0,1,0],[0,0,-1],[0,1,0],[0,0,-1],[0,1,0],[0,0,-1]])
def rot(ax,t):
 ax=ax/np.linalg.norm(ax);x,y,z=ax;c=np.cos(t);s=np.sin(t);v=1-c;return np.array([[c+x*x*v,x*y*v-z*s,x*z*v+y*s],[y*x*v+z*s,c+y*y*v,y*z*v-x*s],[z*x*v-y*s,z*y*v+x*s,c+z*z*v]])
C=np.eye(4);pr=np.zeros(3)
for i in range(7):
 T=np.eye(4);T[:3,3]=p[i]-pr;C=C@T;T=np.eye(4);T[:3,:3]=rot(a[i],q[i]);C=C@T;pr=p[i]
pc=C[:3,:3]@(np.array([.1199,.0315,1.5791])-p[-1])+C[:3,3];R=C[:3,:3]@np.diag([-1,1,1]);f=480/2/np.tan(np.deg2rad(41.8/2));
for lo,hi in [(.55,.69),(.35,.5),(.20,.32)]:
 mask=(im[:,:,0]<100)&(d>=lo)&(d<=hi);ys,xs=np.where(mask);print('bin',lo,hi,'n',len(xs))
 if len(xs):
  u=np.median(xs);v=np.median(ys);dd=np.median(d[ys,xs]);loc=np.array([(u-320)*dd/f,(240-v)*dd/f,dd]);print(' med uv/d',u,v,dd,'xyz',(pc+R@loc).round(3),'bbox',xs.min(),xs.max(),ys.min(),ys.max())
